#include <stdio.h>
#include <stdlib.h>
#include <math.h>
// Compute normalized L2 (cosine) similarity between two P3 PPM files of same dims.
int rd(FILE*f,int*v){int c,n=0;do{c=fgetc(f);}while(c==' '||c=='\n'||c=='\t'||c=='\r');if(c==EOF)return 0;while(c>='0'&&c<='9'){n=n*10+(c-'0');c=fgetc(f);}*v=n;return 1;}
int main(int argc,char**argv){
  FILE*a=fopen(argv[1],"r"),*b=fopen(argv[2],"r");
  int wa,ha,wb,hb,m;
  char la[4],lb[4];
  fscanf(a,"%3s",la);rd(a,&wa);rd(a,&ha);rd(a,&m);
  fscanf(b,"%3s",lb);rd(b,&wb);rd(b,&hb);rd(b,&m);
  if(wa!=wb||ha!=hb){printf("DIM MISMATCH %dx%d vs %dx%d\n",wa,ha,wb,hb);return 1;}
  long n=(long)wa*ha*3;
  double dot=0,na=0,nb=0;
  for(long i=0;i<n;i++){
    int x,y;rd(a,&x);rd(b,&y);
    dot+= (double)x*y; na+=(double)x*x; nb+=(double)y*y;
  }
  printf("cosine = %.6f\n", dot/(sqrt(na)*sqrt(nb)));
  return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>

int main(){
  int W=2400,H=1800;
  unsigned char*buf=malloc((long)W*H*3);
  for(int y=0;y<H;y++){
    for(int x=0;x<W;x++){
      double r,g,b;
      double sx=x-1199.0, sy=y-990.0;
      double d2=(sx*sx+sy*sy)/(184.0*184.0);
      if(d2<1.0){
        double lit=(990.0-y)/184.0;
        if(lit<0)lit=0; if(lit>1)lit=1;
        lit=lit*lit;
        r=51+97*lit; g=10+19*lit; b=10+19*lit;
      }else if(y<900){
        double yn=y/900.0, xn=(x-1200.0)/1200.0, x2=xn*xn;
        r=143.561+43.95*yn+(15.195-11.699*yn)*x2;
        g=188.279+26.467*yn+(9.226-7.232*yn)*x2;
        b=255;
      }else{
        double t=y-899.0;
        int tx=(int)floor(1.5*sx/t);
        int tz=(int)floor(1351.0/t);
        int s=(tx+tz)%2; if(s<0)s+=2;
        double v=s?152:67;
        r=g=b=v;
      }
      long idx=((long)y*W+x)*3;
      buf[idx++]=r;buf[idx++]=g;buf[idx++]=b;
    }
  }
  FILE*f=fopen("reconstructed.ppm","wb");
  fprintf(f,"P6\n%d %d\n255\n",W,H);
  fwrite(buf,1,(long)W*H*3,f);
  fclose(f);
  return 0;
}

