#include <stdio.h>
#include <stdlib.h>
#include <math.h>
int rd(FILE*f,int*v){int c,n=0;do{c=fgetc(f);}while(c==' '||c=='\n'||c=='\t'||c=='\r');if(c==EOF)return 0;while(c>='0'&&c<='9'){n=n*10+(c-'0');c=fgetc(f);}*v=n;return 1;}
int main(int argc,char**argv){
  FILE*a=fopen(argv[1],"r"),*b=fopen(argv[2],"r");
  int wa,ha,wb,hb,m;
  rd(a,&wa);rd(a,&ha);rd(a,&m); rd(b,&wb);rd(b,&hb);rd(b,&m);
  long n=(long)wa*ha*3;
  double dot=0,na=0,nb=0,d2=0;
  for(long i=0;i<n;i++){
    int x,y;rd(a,&x);rd(b,&y);
    double di=x-y; d2+=di*di;
    dot+=(double)x*y;na+=(double)x*x;nb+=(double)y*y;
  }
  double la=sqrt(na),lb=sqrt(nb),lerr=sqrt(d2);
  printf("cosine      = %.6f\n", dot/(la*lb));
  printf("1-||e||/||a||= %.6f\n", 1-lerr/la);
  printf("1-||e||/||b||= %.6f\n", 1-lerr/lb);
  printf("1-||e||/(||a||+||b||)= %.6f\n", 1-lerr/(la+lb));
  printf("1-||e||/(||a||*||b||)= %.6f\n", 1-lerr/(la*lb));
  // normalized correlation-like: exp(-d2/na)
  printf("exp(-||e||^2/||a||^2)= %.6f\n", exp(-d2/na));
  return 0;
}

